Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_inorder_non_empty_tree(void) {
    struct node* root = NULL;
    int values[] = {50, 30, 70, 20, 40, 60, 80};
    int size = sizeof(values) / sizeof(values[0]);

    root = helper_build_tree(values, size);
    TEST_ASSERT_NOT_NULL(root);

    stdout_capture_t* cap = capture_stdout_start();
    TEST_ASSERT_NOT_NULL(cap);

    inorder(root);

    char* captured = capture_stdout_stop(cap);
    TEST_ASSERT_NOT_NULL(captured);

    assert_stdout_equals(cap, "20 30 40 50 60 70 80 ");

    free(captured);
    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_inorder_non_empty_tree);
    return UNITY_END();
}

